const empresaId = $json.empresa_id;
const store = $getWorkflowStaticData('global');
store.ifoodTokens = store.ifoodTokens || {};
const cached = store.ifoodTokens[empresaId];
const valido = !!(cached && cached.expiresAt > Date.now() + 60000);
return [{
  json: {
    ...$json,
    access_token: valido ? cached.accessToken : null,
    token_valido: valido,
  },
}];

const ctx = $('Checar token em cache').item.json;
const store = $getWorkflowStaticData('global');
store.ifoodTokens = store.ifoodTokens || {};
store.ifoodTokens[ctx.empresa_id] = {
  accessToken: $json.accessToken,
  expiresAt: Date.now() + (($json.expiresIn || 21600) * 1000),
};
return [{
  json: { ...ctx, access_token: $json.accessToken, token_valido: true },
}];

const now = new Date();
const end = new Date(now.getTime() - 1*24*60*60*1000);
const begin = new Date(end.getTime() - 7*24*60*60*1000);
const fmt = (d) => d.toISOString().slice(0,10);
return [{ json: { ...$json, beginSalesDate: fmt(begin), endSalesDate: fmt(end) } }];

const sales = $json.sales || [];
return sales.map(sale => {
  const events = sale.orderEvents || [];
  const findEvent = (code) => events.find(e => e.fullCode === code);
  const confirmedEvt = findEvent('CONFIRMED');
  const prepStartedEvt = findEvent('PREPARATION_STARTED');
  const gross = sale.saleGrossValue || {};

  // Comissao/repasse: billingEntries sempre veio [] pra essa loja sandbox,
  // entao os nomes de campo (type vs entryType, os valores do enum de tipo)
  // e o parseamento abaixo sao inferidos da documentacao, NAO confirmados
  // contra um payload real. Assim que a primeira venda com billingEntries
  // nao-vazio chegar, conferir em marketplace_pedidos.metadata->billingSummary
  // (guarda o JSON bruto) se a categorizacao abaixo bateu; se nao bateu,
  // so ajustar os regexes/nomes de campo aqui, sem redesenhar nada.
  const billing = sale.billingSummary || {};
  const entries = Array.isArray(billing.billingEntries) ? billing.billingEntries : [];
  const temEntries = entries.length > 0;
  const textoEntry = (e) => `${e.type || e.entryType || ''} ${e.description || e.desc || ''}`.toUpperCase();
  // abs(): as colunas taxa_* representam o TAMANHO da taxa (pra somar/exibir
  // como custo positivo no dashboard), nao um lancamento contabil com sinal --
  // billingEntries provavelmente vem negativo (debito da loja); se algum tipo
  // vier como credito de verdade isso vai inflar 'outrasTaxas' por engano,
  // outro ponto pra conferir no primeiro payload real.
  const valorEntry = (e) => Math.abs(Number(e.amount ?? e.value ?? 0));
  const somaSe = (regex) => entries.filter(e => regex.test(textoEntry(e))).reduce((s, e) => s + valorEntry(e), 0);
  const taxaComissao = somaSe(/COMISS|COMMISSION/);
  const taxaGateway = somaSe(/GATEWAY|PAGAMENTO|PROCESSING/);
  const taxaEntrega = somaSe(/ENTREGA|DELIVERY|LOGISTIC/);
  const somaConhecida = taxaComissao + taxaGateway + taxaEntrega;
  const somaTotal = entries.reduce((s, e) => s + valorEntry(e), 0);
  const outrasTaxas = temEntries ? (somaTotal - somaConhecida) : null;
  // saleBalance = valor liquido a repassar pra loja, unico campo de repasse
  // confirmado (por nome) na documentacao publica -- pode estar em
  // billingSummary.saleBalance ou direto em sale.saleBalance, tenta os dois.
  const valorLiquido = billing.saleBalance ?? sale.saleBalance ?? null;

  return {
    json: {
      marketplace_order_id: sale.id,
      valor_bruto: (gross.bag || 0) + (gross.deliveryFee || 0) + (gross.serviceFee || 0),
      status_marketplace: sale.currentStatus || null,
      criado_em: sale.createdAt || null,
      confirmado_em: confirmedEvt ? confirmedEvt.createdAt : null,
      preparo_iniciado_em: prepStartedEvt ? prepStartedEvt.createdAt : null,
      billing_summary: JSON.stringify(sale.billingSummary || null),
      payments: JSON.stringify(sale.payments || null),
      taxa_comissao: temEntries ? taxaComissao : null,
      taxa_gateway: temEntries ? taxaGateway : null,
      taxa_entrega_marketplace: temEntries ? taxaEntrega : null,
      outras_taxas: outrasTaxas,
      valor_liquido_recebido: valorLiquido,
    },
  };
});

// Agrupa financial-events por pedido (reference.id) e soma por tipo de taxa.
// NAO CONFIRMADO contra payload real - essa loja sandbox nunca teve
// financial-events preenchido (testado ao vivo em 2026-07-30, retornou []).
// Assim que o primeiro periodo com eventos reais chegar, conferir em
// marketplace_pedidos.metadata->financialEventsRaw se a categorizacao por
// 'name' abaixo bateu; se nao bateu, so ajustar o switch, sem redesenhar nada.
const events = $json.financialEvents || [];
const porPedido = {};
for (const e of events) {
  if (!e.reference || e.reference.type !== 'ORDER') continue;
  const orderId = e.reference.id;
  if (!porPedido[orderId]) {
    porPedido[orderId] = {
      marketplace_order_id: orderId,
      taxa_comissao: 0,
      taxa_gateway: 0,
      taxa_entrega_marketplace: 0,
      outras_taxas: 0,
      data_prevista_repassado: null,
      eventosRaw: [],
    };
  }
  const p = porPedido[orderId];
  const abs = Math.abs(Number((e.amount && e.amount.value) || 0));
  switch (e.name) {
    case 'ORDER_COMMISSION': p.taxa_comissao += abs; break;
    case 'PAYMENT_TRANSACTION_FEE': p.taxa_gateway += abs; break;
    case 'DELIVERY_FEE_IFOOD': p.taxa_entrega_marketplace += abs; break;
    case 'ORDER_PAYMENT': break; // valor do pedido em si, nao e taxa
    default: p.outras_taxas += abs;
  }
  const expected = e.settlement && e.settlement.expectedDate;
  if (expected && (!p.data_prevista_repassado || expected > p.data_prevista_repassado)) {
    p.data_prevista_repassado = expected;
  }
  p.eventosRaw.push(e);
}
return Object.values(porPedido).map((p) => ({ json: p }));

// Achata os settlements - podem vir como item direto no array raiz
// (RENEGOCIADA/REGISTRO_RECEBIVEIS/REPASSE/BOLETO) ou agrupados por periodo
// com closingItems aninhados (varios REPASSE de uma vez).
// NAO CONFIRMADO contra payload real - settlements sempre veio vazio
// (balance:0) pra essa loja sandbox (testado ao vivo em 2026-07-30).
const data = $json;
const out = [];
for (const grupo of (data.settlements || [])) {
  if (Array.isArray(grupo.closingItems)) {
    for (const item of grupo.closingItems) {
      out.push({
        json: {
          transaction_id: item.transactionId || item.id || null,
          tipo: item.type || 'REPASSE',
          status: item.status || null,
          valor: Number(item.amount ?? item.anticipatedPaymentAmount ?? item.originalPaymentAmount ?? 0),
          data_pagamento: item.paymentDate || item.anticipatedPaymentDate || null,
          data_inicio_periodo: grupo.startDateCalculation || null,
          data_fim_periodo: grupo.endDateCalculation || null,
          raw: item,
        },
      });
    }
  } else {
    out.push({
      json: {
        transaction_id: grupo.transactionId || grupo.id || null,
        tipo: grupo.type || null,
        status: grupo.status || null,
        valor: Number(grupo.amount ?? 0),
        data_pagamento: grupo.paymentDate || null,
        data_inicio_periodo: null,
        data_fim_periodo: null,
        raw: grupo,
      },
    });
  }
}
return out;

const raw = typeof $json.data === 'string' ? $json.data : String($json.data || '');
let parsed;
try {
  parsed = raw.trim() ? JSON.parse(raw) : { sales: [], total: 0 };
} catch (e) {
  // iFood retorna 204 (corpo vazio) quando nao ha vendas no periodo -- o node
  // HTTP em modo texto nunca lanca erro por isso, mas o parse falharia sem
  // esse fallback. Tambem cobre qualquer outro corpo nao-JSON inesperado.
  parsed = { sales: [], total: 0, parse_error: raw.slice(0, 300) };
}
return [{ json: parsed }];
